// ---- Flag translation tables ----
struct FlagBit {
  uint64_t Guest;
  uint64_t Host;
};
struct FieldValue {
  uint64_t Guest;
  uint64_t Host;
};
struct FlagField {
  uint64_t GuestMask;
  uint64_t HostMask;
  const FieldValue* Values;
  size_t NumValues;
};
struct FlagSet {
  const FlagBit* Bits;
  size_t NumBits;
  const FlagField* Fields;
  size_t NumFields;
  // Bits that exist on one architecture only.
  uint64_t GuestOnly;
  uint64_t HostOnly;
};

