// Returns false when a value does not fit the guest field (the kernel answers EOVERFLOW).
inline bool ConvertStat(const HostStat& H, GuestStat* G) {
  *G = GuestStat {};
  bool Fits = true;
  G->st_dev = H.st_dev;
  Fits &= static_cast<decltype(H.st_dev)>(G->st_dev) == H.st_dev;
  G->st_ino = H.st_ino;
  Fits &= static_cast<decltype(H.st_ino)>(G->st_ino) == H.st_ino;
  G->st_mode = H.st_mode;
  Fits &= static_cast<decltype(H.st_mode)>(G->st_mode) == H.st_mode;
  G->st_nlink = H.st_nlink;
  Fits &= static_cast<decltype(H.st_nlink)>(G->st_nlink) == H.st_nlink;
  G->st_uid = H.st_uid;
  Fits &= static_cast<decltype(H.st_uid)>(G->st_uid) == H.st_uid;
  G->st_gid = H.st_gid;
  Fits &= static_cast<decltype(H.st_gid)>(G->st_gid) == H.st_gid;
  G->st_rdev = H.st_rdev;
  Fits &= static_cast<decltype(H.st_rdev)>(G->st_rdev) == H.st_rdev;
  G->st_size = H.st_size;
  Fits &= static_cast<decltype(H.st_size)>(G->st_size) == H.st_size;
  G->st_blksize = H.st_blksize;
  Fits &= static_cast<decltype(H.st_blksize)>(G->st_blksize) == H.st_blksize;
  G->st_blocks = H.st_blocks;
  Fits &= static_cast<decltype(H.st_blocks)>(G->st_blocks) == H.st_blocks;
  G->st_atime_sec = H.st_atime_sec;
  Fits &= static_cast<decltype(H.st_atime_sec)>(G->st_atime_sec) == H.st_atime_sec;
  G->st_atime_nsec = H.st_atime_nsec;
  Fits &= static_cast<decltype(H.st_atime_nsec)>(G->st_atime_nsec) == H.st_atime_nsec;
  G->st_mtime_sec = H.st_mtime_sec;
  Fits &= static_cast<decltype(H.st_mtime_sec)>(G->st_mtime_sec) == H.st_mtime_sec;
  G->st_mtime_nsec = H.st_mtime_nsec;
  Fits &= static_cast<decltype(H.st_mtime_nsec)>(G->st_mtime_nsec) == H.st_mtime_nsec;
  G->st_ctime_sec = H.st_ctime_sec;
  Fits &= static_cast<decltype(H.st_ctime_sec)>(G->st_ctime_sec) == H.st_ctime_sec;
  G->st_ctime_nsec = H.st_ctime_nsec;
  Fits &= static_cast<decltype(H.st_ctime_nsec)>(G->st_ctime_nsec) == H.st_ctime_nsec;
  return Fits;
}

